SELECT event_occured_id, detector_proc_id, tracking_process_id, request_tracking_id, event_occured_time, event_transmitted_status, event_transmitted_time, event_occured_msg FROM event_occured_info WHERE 1=1
AND request_tracking_id = #{requestTrackingId}
AND tracking_process_id = #{trackingProcessId}
AND event_occured_id = #{eventOccuredId}

SELECT event_occured_id, detector_proc_id, tracking_process_id, request_tracking_id, event_occured_time, event_transmitted_status, event_transmitted_time, event_occured_msg FROM event_occured_info WHERE 1=1
AND request_tracking_id = #{requestTrackingId}
AND tracking_process_id = #{trackingProcessId}
AND event_occured_id = #{eventOccuredId}
ORDER BY event_occured_id DESC

